import{_ as l,l as s,o as e,c as o,v as t,p,x as i,d,i as n,S as c}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"内核旁路 DPDK","description":"","frontmatter":{"title":"内核旁路 DPDK","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dpdk-kernel-bypass.md","filePath":"cs/dpdk-kernel-bypass.md","lastUpdated":1789023840000}'),D={name:"cs/dpdk-kernel-bypass.md"};function u(P,a,h,f,_,m){const r=s("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="内核旁路-dpdk" tabindex="-1">内核旁路 DPDK <a class="header-anchor" href="#内核旁路-dpdk" aria-label="Permalink to &quot;内核旁路 DPDK&quot;">​</a></h1><div class="epigraph"><p>DPDK 用用户态驱动轮询网卡队列：包在用户 mbuf 池里走完，不经过 sk_buff、NAPI 与套接字。</p><footer>—— 据 DPDK 程序员指南；Linux VFIO/UIO 对用户态 I/O 的支持说明</footer></div><p><a href="/cs/xdp-ebpf">XDP</a> 仍在内核。<a href="/cs/io-polling">轮询 I/O</a> 在存储侧已见 busy-wait。缺口是 <strong>网络旁路</strong>：DPDK 一类框架把 NIC 绑给进程。本课讲 OS 位置，不是教程。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>内核路径：中断/NAPI、skb、协议、系统调用。旁路：进程 mmap 寄存器与描述符环，poll，自己实现以太网/IP 或把帧再注入内核。缺口：设备从内核解绑（<code>vfio-pci</code>），IOMMU 保护 DMA；无内核 TCP 则要用户态栈或只做 L2 转发；与普通 socket 应用不兼容。本课不把每家 PMD 列成表。</p><p><span class="marginnote">AF_XDP 是折中：内核驱动填 umem，用户 poll。DPDK 更彻底。CPU 隔离与 <a href="/cs/cpuidle-cstate">cpuidle</a> 冲突：轮询核不睡眠。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>启动：绑定网卡到 vfio，hugepage 池。运行：每核一队列 RSS，收 mbuf，处理，发。需要与内核互通时：tap/KNI 或 virtio。对照 NVMe 用户态（SPDK）：同样是 poll + 用户驱动。对照 tun：tun 仍经内核虚拟设备；DPDK 直接硬件。</p>',8)),(e(),p(c,null,{default:i(()=>[n(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20NIC%5B%22%E7%BD%91%E5%8D%A1%E9%98%9F%E5%88%97%22%5D%20--%3E%20UIO%5B%22%E7%94%A8%E6%88%B7%E6%80%81%20PMD%22%5D%0A%20%20UIO%20--%3E%20MBUF%5B%22mbuf%20%E6%B1%A0%22%5D%0A%20%20MBUF%20--%3E%20APP%5B%22%E7%94%A8%E6%88%B7%E5%8D%8F%E8%AE%AE%E6%88%96%E8%BD%AC%E5%8F%91%22%5D%0A%20%20KERN%5B%22sk_buff%20%E8%B7%AF%E5%BE%84%22%5D%20-.-%3E%7C%22%E4%B8%8D%E7%BB%8F%E8%BF%87%22%7C%20UIO%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>旁路用 CPU 与隔离核换最低每包成本，适合网关与 NFV。OS 仍提供：IOMMU、中断（可选）、内存、调度其余核。不要写成「不用操作系统」。与 <a href="/cs/blkio-cgroup">blkio</a>：旁路流量可能看不见内核 netfilter，策略要在用户态重做。</p><p>安全：用户进程 DMA 能力靠 IOMMU 限制到该设备；配置错误则危险。</p><p>实现上：绑定 vfio-pci 后内核不再收包，ssh 会断，要留管理口。hugepage 泄漏会把机器钉死。与内核互通常靠 virtio-user 或 tap，那一段又回到 skb。 读法上只引用<a href="/cs/xdp-ebpf">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「网络栈 / 收发路径」课序里，对象是 <strong>内核旁路 DPDK</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 DPDK 的全部库（timer、cryptodev）。不保证实时许可证下的延迟数字。下一课回到内核路径上的并行：RSS 与多队列。</p><p>版本字段会变，课序钉的是机制对象「内核旁路 DPDK」，不是某一主线内核的结构体名。 后课默认：包可以完全在用户态收发。内核多队列如何把流散到 CPU，下一课 RSS。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DPDK 用户态轮询 NIC，绕过协议栈。</li><li>依赖 VFIO/IOMMU；与 socket API 分裂。</li><li>RSS 多队列是下一课。</li><li>出处：DPDK 文档；VFIO；Linux UIO。</li></ul>',11))])}const k=l(D,[["render",u]]);export{b as __pageData,k as default};
